"""Atomic file repository for ResearchRun state."""

from __future__ import annotations

import os
from pathlib import Path

from my_search_harness.domain.model import ResearchRun
from my_search_harness.domain.validation import (
    DomainValidationError,
    validate_ref,
    validate_run,
    validate_transition,
)

from .codec import run_from_json, run_to_json


class RevisionConflictError(RuntimeError):
    """The caller attempted to save against a stale state revision."""


class RunAlreadyExistsError(RuntimeError):
    """A run with the requested ID already exists."""


class RunNotFoundError(RuntimeError):
    """No persisted run exists for the requested ID."""


class JsonResearchRunRepository:
    """One-file-per-run repository with optimistic revision checks."""

    def __init__(self, root: str | Path) -> None:
        self._root = Path(root)
        self._root.mkdir(parents=True, exist_ok=True)

    @property
    def root(self) -> Path:
        """Filesystem root for colocated non-authoritative runtime records."""

        return self._root

    def _run_directory(self, run_id: str) -> Path:
        validate_ref(run_id, "run", "run_id")
        return self._root / run_id

    def _state_path(self, run_id: str) -> Path:
        return self._run_directory(run_id) / "state.json"

    def load(self, run_id: str) -> ResearchRun:
        path = self._state_path(run_id)
        try:
            payload = path.read_text(encoding="utf-8")
        except FileNotFoundError as exc:
            raise RunNotFoundError(f"research run {run_id!r} was not found") from exc
        return run_from_json(payload)

    def list_run_ids(self) -> tuple[str, ...]:
        """List authoritative Run snapshots without consulting audit/artifacts."""

        run_ids: list[str] = []
        for path in self._root.iterdir():
            if not path.is_dir() or not (path / "state.json").is_file():
                continue
            validate_ref(path.name, "run", "run directory name")
            run_ids.append(path.name)
        return tuple(sorted(run_ids))

    def create(self, run: ResearchRun) -> None:
        validate_run(run)
        if run.state_revision != 1:
            raise DomainValidationError("a newly created run must start at revision 1")
        run_directory = self._run_directory(run.id)
        state_path = run_directory / "state.json"
        if state_path.exists():
            raise RunAlreadyExistsError(f"research run {run.id!r} already exists")
        run_directory.mkdir(exist_ok=True)
        try:
            self._write_atomic(state_path, run_to_json(run))
        except BaseException:
            temporary = run_directory / "state.json.tmp"
            temporary.unlink(missing_ok=True)
            try:
                run_directory.rmdir()
            except OSError:
                pass
            raise

    def save(self, run: ResearchRun, expected_revision: int) -> None:
        current = self.load(run.id)
        if current.state_revision != expected_revision:
            raise RevisionConflictError(
                f"expected revision {expected_revision}, found "
                f"{current.state_revision}"
            )
        validate_run(run)
        validate_transition(current, run)
        self._write_atomic(self._state_path(run.id), run_to_json(run))

    @staticmethod
    def _write_atomic(path: Path, payload: str) -> None:
        temporary = path.with_name(f"{path.name}.tmp")
        try:
            with temporary.open("w", encoding="utf-8", newline="\n") as stream:
                stream.write(payload)
                stream.flush()
                os.fsync(stream.fileno())
            os.replace(temporary, path)
        except BaseException:
            temporary.unlink(missing_ok=True)
            raise

"""Local filesystem mechanics for derived delivery artifacts."""

from __future__ import annotations

import hashlib
import json
import os
from dataclasses import dataclass
from pathlib import Path

from my_search_harness.domain.model import ArtifactKind, DeliveryBasis
from my_search_harness.domain.validation import DomainValidationError, validate_ref

from .codec import delivery_basis_from_dict, delivery_basis_to_dict


class ArtifactValidationError(RuntimeError):
    """A derived artifact is missing, corrupt, or stale for the current run."""


@dataclass(slots=True, frozen=True, kw_only=True)
class ReportArtifactMetadata:
    artifact_kind: ArtifactKind
    delivery_basis: DeliveryBasis
    content_sha256: str


@dataclass(slots=True, frozen=True, kw_only=True)
class ReportArtifact:
    artifact_kind: ArtifactKind
    path: Path
    delivery_basis: DeliveryBasis
    content_sha256: str


class LocalArtifactStore:
    """Thin local store for the single V1 report artifact."""

    def __init__(self, root: str | Path) -> None:
        self._root = Path(root)
        self._root.mkdir(parents=True, exist_ok=True)

    def write_report(
        self,
        run_id: str,
        content: str,
        delivery_basis: DeliveryBasis,
    ) -> ReportArtifact:
        content_bytes = content.encode("utf-8")
        content_sha256 = hashlib.sha256(content_bytes).hexdigest()
        artifact_directory = self._artifact_directory(run_id)
        artifact_directory.mkdir(parents=True, exist_ok=True)
        report_path = artifact_directory / "report.md"
        metadata_path = artifact_directory / "report.meta.json"

        self._write_atomic(report_path, content_bytes)
        basis_data = delivery_basis_to_dict(delivery_basis)
        if basis_data is None:
            raise ArtifactValidationError("report delivery basis must not be null")
        metadata = {
            "artifact_kind": ArtifactKind.REPORT.value,
            "delivery_basis": basis_data,
            "content_sha256": content_sha256,
        }
        metadata_bytes = (json.dumps(metadata, indent=2, sort_keys=True) + "\n").encode(
            "utf-8"
        )
        self._write_atomic(metadata_path, metadata_bytes)

        return ReportArtifact(
            artifact_kind=ArtifactKind.REPORT,
            path=report_path,
            delivery_basis=delivery_basis,
            content_sha256=content_sha256,
        )

    def read_report_metadata(self, run_id: str) -> ReportArtifactMetadata:
        metadata_path = self._artifact_directory(run_id) / "report.meta.json"
        try:
            payload = metadata_path.read_text(encoding="utf-8")
        except FileNotFoundError as exc:
            raise ArtifactValidationError("report metadata is missing") from exc
        except (OSError, UnicodeError) as exc:
            raise ArtifactValidationError("report metadata cannot be read") from exc

        try:
            value = json.loads(payload)
            if not isinstance(value, dict) or set(value) != {
                "artifact_kind",
                "delivery_basis",
                "content_sha256",
            }:
                raise ArtifactValidationError(
                    "report metadata must contain exactly the V1 provenance fields"
                )
            artifact_kind = ArtifactKind(value["artifact_kind"])
            delivery_basis = delivery_basis_from_dict(value["delivery_basis"])
            content_sha256 = value["content_sha256"]
            if delivery_basis is None:
                raise ArtifactValidationError(
                    "report metadata delivery basis must not be null"
                )
            if (
                not isinstance(content_sha256, str)
                or len(content_sha256) != 64
                or any(
                    character not in "0123456789abcdef" for character in content_sha256
                )
            ):
                raise ArtifactValidationError(
                    "report metadata content_sha256 must be a lowercase SHA-256 digest"
                )
        except ArtifactValidationError:
            raise
        except (DomainValidationError, KeyError, TypeError, ValueError) as exc:
            raise ArtifactValidationError("report metadata is invalid") from exc

        return ReportArtifactMetadata(
            artifact_kind=artifact_kind,
            delivery_basis=delivery_basis,
            content_sha256=content_sha256,
        )

    def validate_report(
        self, run_id: str, expected_basis: DeliveryBasis | None
    ) -> ReportArtifact:
        report_path = self._artifact_directory(run_id) / "report.md"
        try:
            content = report_path.read_bytes()
        except FileNotFoundError as exc:
            raise ArtifactValidationError("report content is missing") from exc
        except OSError as exc:
            raise ArtifactValidationError("report content cannot be read") from exc

        metadata = self.read_report_metadata(run_id)
        if metadata.artifact_kind is not ArtifactKind.REPORT:
            raise ArtifactValidationError("report metadata has the wrong artifact kind")
        actual_sha256 = hashlib.sha256(content).hexdigest()
        if actual_sha256 != metadata.content_sha256:
            raise ArtifactValidationError(
                "report content digest does not match metadata"
            )
        if metadata.delivery_basis != expected_basis:
            raise ArtifactValidationError(
                "report delivery basis does not match the current run"
            )

        return ReportArtifact(
            artifact_kind=ArtifactKind.REPORT,
            path=report_path,
            delivery_basis=metadata.delivery_basis,
            content_sha256=metadata.content_sha256,
        )

    def _artifact_directory(self, run_id: str) -> Path:
        validate_ref(run_id, "run", "run_id")
        return self._root / run_id / "artifacts"

    @staticmethod
    def _write_atomic(path: Path, payload: bytes) -> None:
        temporary = path.with_name(f"{path.name}.tmp")
        try:
            with temporary.open("wb") as stream:
                stream.write(payload)
                stream.flush()
                os.fsync(stream.fileno())
            os.replace(temporary, path)
        except BaseException:
            temporary.unlink(missing_ok=True)
            raise

"""Append-only operational audit records that never reconstruct Research State."""

from __future__ import annotations

import json
import math
import os
from dataclasses import asdict, dataclass, field
from datetime import datetime
from pathlib import Path
from typing import Protocol, TypeAlias

from my_search_harness.domain.model import utc_now
from my_search_harness.domain.validation import validate_ref


AuditScalar: TypeAlias = str | int | float | bool | None


@dataclass(slots=True, frozen=True, kw_only=True)
class AuditEvent:
    run_id: str
    state_revision: int
    actor: str
    action: str
    outcome: str = "SUCCESS"
    reason: str | None = None
    provider_outcome: str | None = None
    details: dict[str, AuditScalar] = field(default_factory=dict)
    timestamp: datetime = field(default_factory=utc_now)


class AuditSink(Protocol):
    def append(self, event: AuditEvent) -> None: ...


class AuditAppendError(RuntimeError):
    """State/action succeeded or was attempted, but its audit append failed."""

    def __init__(self, event: AuditEvent) -> None:
        super().__init__(
            f"audit append failed after {event.action} at revision "
            f"{event.state_revision}"
        )
        self.event = event


class AuditReadError(RuntimeError):
    """Audit diagnostics cannot parse the append-only log."""


class LocalAuditLog:
    """One JSON line per event; deliberately independent from state repository reads."""

    def __init__(self, root: str | Path) -> None:
        self._root = Path(root)
        self._root.mkdir(parents=True, exist_ok=True)

    def append(self, event: AuditEvent) -> None:
        self._validate_event(event)
        path = self._event_path(event.run_id)
        path.parent.mkdir(parents=True, exist_ok=True)
        payload = self._event_to_json(event).encode("utf-8")
        try:
            descriptor = os.open(
                path,
                os.O_APPEND | os.O_CREAT | os.O_WRONLY,
                0o600,
            )
            try:
                written = 0
                while written < len(payload):
                    chunk_size = os.write(descriptor, payload[written:])
                    if chunk_size == 0:
                        raise OSError("audit append wrote zero bytes")
                    written += chunk_size
                os.fsync(descriptor)
            finally:
                os.close(descriptor)
        except OSError as exc:
            raise AuditAppendError(event) from exc

    def read(self, run_id: str) -> tuple[AuditEvent, ...]:
        path = self._event_path(run_id)
        try:
            lines = path.read_text(encoding="utf-8").splitlines()
        except FileNotFoundError:
            return ()
        except (OSError, UnicodeError) as exc:
            raise AuditReadError("events.jsonl cannot be read") from exc
        events: list[AuditEvent] = []
        for line_number, line in enumerate(lines, start=1):
            try:
                value = json.loads(line)
                if not isinstance(value, dict) or set(value) != {
                    "action",
                    "actor",
                    "details",
                    "outcome",
                    "provider_outcome",
                    "reason",
                    "run_id",
                    "state_revision",
                    "timestamp",
                }:
                    raise ValueError("unexpected event fields")
                event = AuditEvent(
                    run_id=value["run_id"],
                    state_revision=value["state_revision"],
                    actor=value["actor"],
                    action=value["action"],
                    outcome=value["outcome"],
                    reason=value["reason"],
                    provider_outcome=value["provider_outcome"],
                    details=value["details"],
                    timestamp=datetime.fromisoformat(value["timestamp"]),
                )
                self._validate_event(event)
            except (KeyError, TypeError, ValueError) as exc:
                raise AuditReadError(
                    f"events.jsonl line {line_number} is invalid"
                ) from exc
            events.append(event)
        return tuple(events)

    def _event_path(self, run_id: str) -> Path:
        validate_ref(run_id, "run", "run_id")
        return self._root / run_id / "events.jsonl"

    @staticmethod
    def _event_to_json(event: AuditEvent) -> str:
        value = asdict(event)
        value["timestamp"] = event.timestamp.isoformat()
        return (
            json.dumps(
                value,
                sort_keys=True,
                separators=(",", ":"),
                allow_nan=False,
            )
            + "\n"
        )

    @staticmethod
    def _validate_event(event: object) -> None:
        if not isinstance(event, AuditEvent):
            raise ValueError("audit sink requires AuditEvent")
        validate_ref(event.run_id, "run", "audit.run_id")
        if (
            not isinstance(event.state_revision, int)
            or isinstance(event.state_revision, bool)
            or event.state_revision < 1
        ):
            raise ValueError("audit state_revision must be a positive integer")
        for name, value in (
            ("actor", event.actor),
            ("action", event.action),
            ("outcome", event.outcome),
        ):
            if not isinstance(value, str) or not value:
                raise ValueError(f"audit {name} must be a non-empty string")
        for name, optional_value in (
            ("reason", event.reason),
            ("provider_outcome", event.provider_outcome),
        ):
            if optional_value is not None and not isinstance(optional_value, str):
                raise ValueError(f"audit {name} must be a string or None")
        if not isinstance(event.details, dict) or not all(
            isinstance(key, str)
            and isinstance(value, (str, int, float, bool, type(None)))
            and not (isinstance(value, float) and not math.isfinite(value))
            for key, value in event.details.items()
        ):
            raise ValueError("audit details must contain JSON scalar values")
        if (
            not isinstance(event.timestamp, datetime)
            or event.timestamp.tzinfo is None
            or event.timestamp.utcoffset() is None
        ):
            raise ValueError("audit timestamp must be timezone-aware")


def append_audit(sink: AuditSink | None, event: AuditEvent) -> None:
    """Append if configured and normalize sink failures into an explicit error."""

    if sink is None:
        return
    try:
        sink.append(event)
    except AuditAppendError:
        raise
    except Exception as exc:
        raise AuditAppendError(event) from exc

